def claim(sock)
  @mutex.synchronize do
    return nil if @processing_socks.key?(sock)

    info = @ack_waitings.find { |info| info.sock == sock }
    return nil unless info

    @processing_socks[sock] = true
    info
  end
end

def release(sock, info)
  @mutex.synchronize do
    @processing_socks.delete(sock)
    @ack_waitings.delete(info)
  end
end

